        next_state = current_state;
        case (current_state)
            WALK_LEFT: begin
                if (dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end
                end
            end
            WALK_RIGHT: begin
                if (dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    if (bump_left) begin
                        next_state = WALK_LEFT;
                    end
                end
            end
            FALLING: begin
                if (ground) begin
                    next_state = was_walking_left ? WALK_LEFT : WALK_RIGHT;
                end
            end
            DIGGING: begin
                if (ground) begin
                    next_state = was_walking_left ? WALK_LEFT : WALK_RIGHT;
                end
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine the current water level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // All sensors asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Determine flow rate based on current and previous sensor states
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (state)
                3: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                0: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

endmodule
